import unittest

from .. import cluster


class TestCluster(unittest.TestCase):

    def test_cluster_empty(self):
        # ensure that calling cluster with no sequences doesn't crash
        out = cluster([])
        self.assertEqual(out.n_clusters, 0)

    def test_cluster_default(self):
        sequences = [
            "",
            "",
            "",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "",
            "",
        ]
        clustering = cluster(sequences)
        unique = sorted(set(clustering.clusters))
        self.assertEqual(unique, [0, 1, 2])

    def test_cluster_c99(self):
        sequences = [
            "",
            "",
            "",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "MATPAYMSITGTKQGLITAGAFTEDSVGNTYQEGHEDQVMVQGFNHEVIIPRDPQSGQPTGQRVHKPVVITKVFDKASPLLLAALTSGERLTKVEIQWYRTSAAGTQEHYYTTVLEDAIIVDIKDYMHNCQDPGNAHFTHLEDVHFTYRKITWTHEVSGTSGSDDWRSPVAG",
            "",
            "",
        ]
        clustering = cluster(sequences, identity_threshold=0.99)
        unique = sorted(set(clustering.clusters))
        self.assertEqual(unique, [0, 1, 2, 3])
